  // ── data-import / onboarding ── the ⚙️ gear opens a SETUP panel: the 🤝 pair-a-device fix-it (oz-handshake)
  //    + a ＋ that drops a Samsung .zip/.json/.csv into the cache → re-renders the card. parsed in your browser,
  //    never sent. live pairing over wifi belongs to the native receiver (see _SPEC-handshake-receiver.md). ──
  const dayName = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const labelDate = s => { const d = new Date(String(s).slice(0, 10) + 'T12:00:00'); return isNaN(d) ? String(s) : dayName[d.getDay()] + ' ' + (d.getMonth() + 1) + '/' + d.getDate() }
  // ── SLEEP NIGHTS — ONE persisted store, ONE shape. import · manual · AI all write here. (the refactor:
  //    nights lived only in-memory → manual adds + imports were LOST on reload. 5 R's: normalizeNight is the
  //    one factory — reuse + pick-one-shape; the store persists — recover; the model is plain + importable.) ──
  const SLEEP_NIGHTS_KEY = 'toto_sleep_nights'
  function normalizeNight(raw) {
    raw = raw || {}
    const iso = String(raw.iso || raw.date || '').slice(0, 10)
    return {
      iso, d: raw.d || labelDate(iso) || '—',
      out:   raw.out  || raw.lightsOut || '—',
      wake:  raw.wake || '—',
      inbed: raw.inbed || '', lightsoff: raw.lightsoff || '', alarm: raw.alarm || '', outbed: raw.outbed || '',
      onset: +raw.onset || 0, deep: +raw.deep || 0, rem: +raw.rem || 0, light: +raw.light || 0, awake: +raw.awake || 0, eff: +raw.eff || 0,
      note: raw.note || '', manual: !!raw.manual,
    }
  }
  function loadNights() { try { const a = JSON.parse(localStorage.getItem(SLEEP_NIGHTS_KEY) || 'null'); if (Array.isArray(a)) return a } catch (_) {} return null }
  function saveNights(arr) { try { localStorage.setItem(SLEEP_NIGHTS_KEY, JSON.stringify(arr)) } catch (_) {} }
  // the AI's hands (the sleep_* night atoms call these); the human's manual + import paths persist through saveNights too.
  window.sleepNights = () => loadNights() || (REAL && REAL.nights) || []
  window.sleepAddNight = raw => { const n = normalizeNight(raw); const arr = window.sleepNights().slice(); arr.push(n); saveNights(arr); return `night ${n.iso || '?'} saved (${arr.length} total). reopen the 🛏️ sleep card to see it.` }

  // ── 💪 the MISSING exercise write-path — a real global, mirrors the inline shape at the log-submit (date ·
  //    type · start · duration_min · met). the standing-desk drawer + a future wellness bean both write here. ──
  window.exerciseAddLog = raw => {
    raw = raw || {}
    const date = String(raw.iso || raw.date || todayIso()).slice(0, 10)
    const dur = Math.max(0, Math.round(+raw.min || +raw.duration_min || 0))
    const met = +raw.met || (raw.name ? metGuess(raw.name) : 3.5)
    const start = raw.start || '10:00 AM'
    const sess = { date, type: raw.name || raw.type || 'session', start, duration_min: dur, met }
    if (raw.note) sess.note = String(raw.note)
    try { const log = JSON.parse(localStorage.getItem('toto_exercise_log') || '[]'); log.push(sess); localStorage.setItem('toto_exercise_log', JSON.stringify(log)) } catch (_) {}
    const kcal = Math.round(met * 132 * (dur / 60))
    return `logged ${dur}min ${sess.type} · ~${kcal} kcal (${date}). reopen the 🏃 move card to see it.`
  }

  // ── 🧘 the wetware store — "how they felt," machine-readable so the AI + masterReport can read it. one key,
  //    one shape: { [iso]: { day|sleep|food|move : { m:0-4, e:1-4, note } } }. additive; nothing else touches it. ──
  const MOOD_KEY = 'toto_wellness_mood'
  window.moodState = iso => { try { const all = JSON.parse(localStorage.getItem(MOOD_KEY) || '{}'); return iso ? (all[iso] || {}) : all } catch (_) { return iso ? {} : {} } }
  window.moodAddState = (iso, scope, patch) => {
    try {
      const all = JSON.parse(localStorage.getItem(MOOD_KEY) || '{}')
      const day = all[iso] || (all[iso] = {}); const s = day[scope] || (day[scope] = {})
      Object.assign(s, patch || {})
      localStorage.setItem(MOOD_KEY, JSON.stringify(all))
    } catch (_) {}
    return `felt: ${scope} @ ${iso}`
  }

  function buildReport(rows, label) {
    const N = rows.filter(n => (+n.deep || 0) + (+n.rem || 0) + (+n.awake || 0) > 0)   // keep ALL nights → week nav pages your full imported history (tiles recompute per visible week)
    if (!N.length) throw new Error('no usable nights in that file')
    const avg = f => Math.round(N.reduce((a, n) => a + (+f(n) || 0), 0) / N.length)
    const avgDeep = avg(n => n.deep), avgAwake = avg(n => n.awake)
    return {
      week: label || 'imported',
      primary: { awake: (avgAwake / 60).toFixed(1) + 'h', deep: avgDeep + 'm', rem: avg(n => n.rem) + 'm',
        deepNights: N.filter(n => +n.deep > 0).length, baseline: 25,
        deepFillPct: Math.min(100, Math.round(100 * avgDeep / 90)), deepMiss: Math.max(0, 90 - avgDeep) },
      nights: N.map(normalizeNight),   // the ONE shape — import goes through the same factory as manual + AI
    }
  }
  function parseCsv(text) {
    const lines = text.split(/\r?\n/).filter(l => l.trim())
    let hi = lines.findIndex(l => /efficiency|deep|sleep_duration|start_time|date/i.test(l) && l.split(',').length > 2); if (hi < 0) hi = lines.length > 1 ? 1 : 0
    const cols = lines[hi].split(',').map(c => c.trim().toLowerCase()), ix = re => cols.findIndex(c => re.test(c))
    const cE = ix(/efficiency/), cD = ix(/deep/), cR = ix(/rem/), cA = ix(/awake/), cDate = ix(/date|start_time/)
    const rows = lines.slice(hi + 1).map(l => l.split(',')).filter(r => r.length === cols.length).map(r => {
      const g = i => { if (i < 0) return 0; let v = parseFloat((r[i] || '').replace(/[^0-9.\-]/g, '')); v = isFinite(v) ? v : 0; return v > 1440 ? Math.round(v / 60000) : v }
      return { date: (r[cDate] || '').slice(0, 10), eff: g(cE), deep: g(cD), rem: g(cR), awake: g(cA) }
    })
    return buildReport(rows, 'imported · Samsung')
  }
  // ── SAMSUNG EXERCISE, out of the SAME zip (Sum 2026-08-17: "add zip option to fitness"). The importer
  //    already unzipped, already parsed CSV, already normalised rows — it just only ever looked for a file
  //    with "sleep" in the name, so com.samsung.shealth.exercise.csv was sitting in the archive being
  //    skipped. This is a PICKER plus a row mapper; nothing new is being built.
  //    Samsung's headers drift between app versions, so match by MEANING not by position: find the column
  //    whose name contains the word, whatever prefix it carries.
  const colFinder = head => {
    const H = head.map(h => String(h).toLowerCase())
    return (...words) => { for (const w of words) { const i = H.findIndex(h => h.includes(w)); if (i > -1) return i } return -1 }
  }
  function parseExerciseCsv(text) {
    const rows = text.trim().split(/\r?\n/).map(r => r.split(','))
    // Samsung prepends a metadata line above the real header on some exports — take the row that has a time column
    let hi = rows.findIndex(r => r.some(c => /start_?time/i.test(c))); if (hi < 0) hi = 0
    const find = colFinder(rows[hi])
    const iStart = find('start_time', 'start'), iDur = find('duration'), iType = find('exercise_type', 'workout_type', 'type'), iCal = find('calorie')
    if (iStart < 0) throw new Error('no start_time column in the exercise csv')
    let n = 0
    for (const r of rows.slice(hi + 1)) {
      const raw = (r[iStart] || '').trim(); if (!raw) continue
      const d = new Date(raw.replace(' ', 'T')); if (isNaN(d)) continue
      // Samsung logs duration in MILLISECONDS
      const ms = iDur > -1 ? +String(r[iDur]).trim() : 0
      const min = ms > 10000 ? Math.round(ms / 60000) : Math.round(ms || 0)
      if (!min) continue
      const t = iType > -1 ? String(r[iType]).trim() : ''
      window.exerciseAddLog({
        iso: d.toISOString().slice(0, 10),
        start: d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
        min, name: SAMSUNG_EX[t] || t || 'session',
        note: iCal > -1 && r[iCal] ? Math.round(+r[iCal]) + ' kcal (Samsung)' : '',
      })
      n++
    }
    if (!n) throw new Error('found the exercise csv but no rows with a duration')
    return n
  }
  // Samsung stores exercise_type as a NUMBER. The common ones, so the log reads in words not codes.
  const SAMSUNG_EX = { '1001': 'Walk', '1002': 'Run', '11007': 'Cycle', '13001': 'Hike', '14001': 'Swim',
    '15006': 'Yoga', '15005': 'Pilates', '10004': 'Elliptical', '10007': 'Rowing', '0': 'Session' }

  // pull the EXERCISE csv out of a Samsung zip and log every session. returns how many landed.
  window.importSamsungExercise = async file => {
    const JSZip = (await import('https://esm.sh/jszip@3')).default
    const zip = await JSZip.loadAsync(file), names = Object.keys(zip.files)
    const pick = names.find(x => /exercise/i.test(x) && /\.csv$/i.test(x) && !/goal|_type|program|recovery/i.test(x))
      || names.find(x => /(workout|activity)/i.test(x) && /\.csv$/i.test(x))
    if (!pick) throw new Error('no exercise csv inside the zip — Samsung names it com.samsung.shealth.exercise.csv')
    return parseExerciseCsv(await zip.files[pick].async('string'))
  }

  // ── SAMSUNG FOOD, same zip, same road as exercise (Sum 2026-08-17: "if samsung has food tracking,
  //    might as well add it there… looks like you can just trace the path you used for fitness").
  //    It does: com.samsung.health.food_intake.csv. DASH_DATA.food is the live store 40-food.js reads,
  //    so writing there + the same localStorage key means the card sees imports as ordinary meals.
  window.foodAddMeal = raw => {
    raw = raw || {}
    try {
      const F = (window.DASH_DATA = window.DASH_DATA || {}).food = window.DASH_DATA.food || { meals: [], pantry: [] }
      F.meals.push({ id: 'm' + Date.now() + Math.random().toString(36).slice(2, 6),
        d: String(raw.d || todayIso()).slice(0, 10), t: raw.t || 'now', n: raw.n || 'meal',
        kcal: Math.round(+raw.kcal || 0), p: +raw.p || 0, f: +raw.f || 0, c: +raw.c || 0,
        sv: {}, status: 'eaten', note: raw.note || '' })
      localStorage.setItem('toto_food_plan', JSON.stringify(F))
      return true
    } catch (_) { return false }
  }
  window.importSamsungFood = async file => {
    const JSZip = (await import('https://esm.sh/jszip@3')).default
    const zip = await JSZip.loadAsync(file), names = Object.keys(zip.files)
    const pick = names.find(x => /food_intake/i.test(x) && /\.csv$/i.test(x))
      || names.find(x => /food/i.test(x) && /\.csv$/i.test(x) && !/_info|goal|frequent/i.test(x))
    if (!pick) throw new Error('no food csv inside the zip — Samsung names it com.samsung.health.food_intake.csv')
    const rows = (await zip.files[pick].async('string')).trim().split(/\r?\n/).map(r => r.split(','))
    let hi = rows.findIndex(r => r.some(c => /start_?time|create_?time/i.test(c))); if (hi < 0) hi = 0
    const find = colFinder(rows[hi])
    const iT = find('start_time', 'create_time'), iName = find('name', 'title'), iCal = find('calorie'),
          iP = find('protein'), iF = find('total_fat', 'fat'), iC = find('carbohydrate', 'carb')
    if (iT < 0) throw new Error('no time column in the food csv')
    let n = 0
    for (const r of rows.slice(hi + 1)) {
      const raw = (r[iT] || '').trim(); if (!raw) continue
      const dt = new Date(raw.replace(' ', 'T')); if (isNaN(dt)) continue
      const kcal = iCal > -1 ? Math.round(+r[iCal] || 0) : 0
      const nm = (iName > -1 ? String(r[iName]).trim() : '') || 'meal'
      if (!kcal && nm === 'meal') continue          // a row with neither a name nor calories is noise
      window.foodAddMeal({ d: dt.toISOString().slice(0, 10), t: dt.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
        n: nm, kcal, p: iP > -1 ? +r[iP] || 0 : 0, f: iF > -1 ? +r[iF] || 0 : 0, c: iC > -1 ? +r[iC] || 0 : 0,
        note: 'Samsung import' })
      n++
    }
    if (!n) throw new Error('found the food csv but no rows with a name or calories')
    return n
  }

  async function parseImport(file) {
    const n = file.name.toLowerCase()
    if (n.endsWith('.json')) { const j = JSON.parse(await file.text()); return buildReport(Array.isArray(j) ? j : (j.nights || []), j.week || 'imported · JSON') }
    if (n.endsWith('.zip')) {
      const JSZip = (await import('https://esm.sh/jszip@3')).default
      const zip = await JSZip.loadAsync(file), names = Object.keys(zip.files)
      const pick = names.find(x => /sleep/i.test(x) && /\.csv$/i.test(x) && !/stage|goal|score/i.test(x)) || names.find(x => /sleep/i.test(x) && /\.(csv|json)$/i.test(x))
      if (!pick) throw new Error('no sleep file inside the zip')
      const data = await zip.files[pick].async('string')
      return /\.json$/i.test(pick) ? buildReport((JSON.parse(data).nights) || [], 'imported · zip') : parseCsv(data)
    }
    if (n.endsWith('.csv')) return parseCsv(await file.text())
    throw new Error('drop a .zip (Samsung), .json, or .csv')
  }

  const PROFILE_HTML = `
    <div class="sp-block">
      <div class="sp-head">🛏️ sleep profile — wellness reads this · no repeat questions</div>
      <div class="sp-grid">
        <label>goal sleep (hours / night)<input type="number" class="sp-in" data-k="goal" min="1" max="16" step="0.5" placeholder="8"></label>
        <label>how much I actually get<input type="text" class="sp-in" data-k="actual" placeholder="5–6 hours most nights"></label>
        <label class="sp-full">how I get to sleep (routine · timing · what I do)<textarea class="sp-ta" data-k="onset" rows="2" placeholder="warm bath · dim lights by 9pm · no screens"></textarea></label>
        <label class="sp-full">wake routine<textarea class="sp-ta" data-k="wake_routine" rows="2" placeholder="no alarm when possible · keep dark until ready"></textarea></label>
        <label class="sp-full">what helps (exercise · light · meds · food timing · …)<textarea class="sp-ta" data-k="helps" rows="2" placeholder="hard yoga the day before, blackout curtains, consistent wake time"></textarea></label>
        <label class="sp-full">what makes it worse (late meals · alcohol · noise · stress · …)<textarea class="sp-ta" data-k="hurts" rows="2" placeholder="eating after 8pm, any alcohol, anxious days"></textarea></label>
        <label class="sp-full">background (anything wellness should know without asking)<textarea class="sp-ta" data-k="background" rows="3" placeholder="clinical insomniac, migraines, ADHD — structural: need 9–10h in bed for 6h of sleep"></textarea></label>
      </div>
      <button class="sp-save">save profile</button>
      <div class="sp-msg"></div>
    </div>
    <div class="sp-divider"></div>`

  // the shared 🤝 "get your data in" mini — the fix-it that REPLACES the old dev-mode / OAuth dance. every card's
